  EditorSession edit(JSONObject item){if(catalog==null)return null;WindowNetworkState state=state(item);NetworkDraft draft=new NetworkDraft(state.slot,state.config,catalog);if(draft.entry.isEmpty()||draft.mode.equals("random")&&state.connected){JSONObject sub=catalog.subscription(draft.subscriptionId);if(sub!=null&&EntrySelection.strings(sub.optJSONArray("nodes")).contains(state.entry)&&(!draft.mode.equals("random")||draft.pool.contains(state.entry)))draft.entry=state.entry;}ReferenceUi.Modal d=new ReferenceUi.Modal(a,"编辑网络 · "+state.name);final Runnable[] render={null};final boolean[] saving={false};TextView error=ReferenceUi.text(a,"",12,ReferenceUi.RED,false);error.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
    render[0]=()->{d.body.removeAllViews();JSONObject s=catalog.subscription(draft.subscriptionId),e=catalog.exit(draft.exitId);routeRow(d,"入口订阅",s==null?"请选择订阅":s.optString("name"),()->selectSubscription(draft,render[0]));routeRow(d,"入口选择",(draft.mode.equals("manual")?"手动指定":"自动随机")+(draft.entry.isEmpty()?" · 待选择":" · "+NativeNetwork.display(draft.entry)),()->selectEntry(draft,render[0]));routeRow(d,"固定出口",e==null?"请选择固定出口":e.optString("name"),()->selectExit(draft,render[0]));d.body.addView(error);d.resize();};
    d.buttons("取消",d::dismiss,"保存并应用",()->{if(saving[0])return;JSONObject candidate;try{candidate=draft.candidate(catalog);}catch(Exception e){error.setText(e.getMessage());d.resize();return;}saving[0]=true;d.primary().setEnabled(false);d.primary().setText("正在应用…");((Button)d.footer.getChildAt(0)).setText("收起");for(int i=0;i<d.body.getChildCount();i++)d.body.getChildAt(i).setEnabled(false);error.setText("正在保存并应用，收起后操作仍会继续…");error.setTextColor(ReferenceUi.MUTED);d.resize();NetworkBridge.run(a,draft.slot,"apply",candidate,draft.baseline,(ok,message,snapshot)->{if(closed||a.isDestroyed())return;saving[0]=false;reload();if(ok){d.dismiss();Toast.makeText(a,message,Toast.LENGTH_SHORT).show();}else if(d.isShowing()){error.setText(message);error.setTextColor(ReferenceUi.RED);if(message.startsWith("配置已保存")){d.buttons("关闭",d::dismiss,"重新连接",()->{d.dismiss();operate(draft.slot,"reconnect");});}else{d.primary().setEnabled(true);d.primary().setText("保存并应用");((Button)d.footer.getChildAt(0)).setText("取消");for(int i=0;i<d.body.getChildCount();i++)d.body.getChildAt(i).setEnabled(true);}d.resize();}});});render[0].run();d.show();return new EditorSession(d,draft,render[0]);}
  ReferenceUi.Modal selectSubscription(NetworkDraft draft,Runnable changed){ReferenceUi.Modal d=new ReferenceUi.Modal(a,"选择入口订阅");for(int i=0;i<catalog.subscriptions().length();i++){JSONObject s=catalog.subscriptions().optJSONObject(i);choice(d,s.optString("name"),EntrySelection.strings(s.optJSONArray("nodes")).size()+" 个入口",s.optString("id").equals(draft.subscriptionId),()->{boolean different=!s.optString("id").equals(draft.subscriptionId);draft.subscription(s.optString("id"),catalog);if(EntrySelection.strings(s.optJSONArray("nodes")).isEmpty()){d.dismiss();loadPool(s,false,()->{draft.normalize(catalog);draft.pool.addAll(EntrySelection.strings(catalog.subscription(draft.subscriptionId).optJSONArray("nodes")));if(draft.mode.equals("random"))draft.randomize(new Random());changed.run();});}else{if(different){draft.pool.addAll(EntrySelection.strings(s.optJSONArray("nodes")));if(draft.mode.equals("random"))draft.randomize(new Random());}d.dismiss();changed.run();}});}if(catalog.subscriptions().length()==0)d.note("还没有订阅，添加已有订阅后即可选择入口。");d.buttons("取消",d::dismiss,"添加订阅",()->{d.dismiss();subscriptionForm(()->selectSubscription(draft,changed));});d.show();return d;}
