  void loadPool(JSONObject subscription,boolean update,Runnable next){ReferenceUi.Modal d=new ReferenceUi.Modal(a,update?"更新订阅":"读取入口");LinearLayout progress=DesignUi.progress(a,"正在读取 "+subscription.optString("name"),"当前窗口继续使用原连接。");d.body.addView(progress);d.buttons("收起",d::dismiss,"",()->{});d.show();String id=subscription.optString("id");byte[] cache=update?null:catalog.cache(subscription);long stamp=subscription.optLong("updatedAt");NativeNetwork.previewSubscription(Profiles.context(a,Profiles.slot(a)),subscription.optString("url"),cache,(ok,message,nodes,bytes)->{if(closed||a.isDestroyed())return;if(ok){reader.execute(()->{try{NetworkCatalog fresh=new NetworkCatalog(a);fresh.parsed(id,nodes,bytes,cache==null?System.currentTimeMillis():stamp);main.post(()->{if(closed||a.isDestroyed())return;catalog=fresh;boolean advance=d.isShowing();d.dismiss();reload();if(next!=null&&advance)next.run();});}catch(Exception e){main.post(()->{if(!d.isShowing())return;d.body.removeAllViews();d.note("入口已解析，但缓存保存失败或订阅已更新，请重试。");d.buttons("关闭",d::dismiss,"重试",()->{d.dismiss();loadPool(subscription,update,next);});d.resize();});}});}else if(d.isShowing()){d.body.removeAllViews();d.note(message);d.buttons("关闭",d::dismiss,"重试",()->{d.dismiss();loadPool(subscription,update,next);});d.resize();}});}
  void subscriptionForm(Runnable next){ReferenceUi.Modal d=new ReferenceUi.Modal(a,"添加入口订阅");EditText name=DesignUi.input(d.body,"订阅名称","","例如：工作订阅"),url=DesignUi.input(d.body,"订阅地址","","HTTPS · Clash / Mihomo");url.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);TextView error=ReferenceUi.text(a,"",12,ReferenceUi.RED,false);d.body.addView(error);d.buttons("取消",d::dismiss,"保存订阅",()->{String title=name.getText().toString().trim();if(title.isEmpty()){name.setError("填写订阅名称");return;}try{NetworkCatalog fresh=new NetworkCatalog(a);JSONObject s=fresh.addSubscription(title,url.getText().toString().trim());catalog=fresh;d.dismiss();reload();loadPool(s,false,next);}catch(Exception e){error.setText(e.getMessage());d.resize();}});d.show();}
  void exitForm(Runnable next){ReferenceUi.Modal d=new ReferenceUi.Modal(a,"添加固定出口");EditText name=DesignUi.input(d.body,"出口名称","","例如：工作出口"),region=DesignUi.input(d.body,"地区（可选）","","填写你已知的出口地区"),host=DesignUi.input(d.body,"SOCKS5 服务器","","域名或 IP"),port=DesignUi.input(d.body,"端口","","1–65535"),user=DesignUi.input(d.body,"用户名（可选）","",""),password=DesignUi.input(d.body,"密码（可选）","","");port.setInputType(InputType.TYPE_CLASS_NUMBER);password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView error=ReferenceUi.text(a,"",12,ReferenceUi.RED,false);d.body.addView(error);d.buttons("取消",d::dismiss,"保存出口",()->{if(name.getText().toString().trim().isEmpty()){name.setError("填写出口名称");return;}try{int number=Integer.parseInt(port.getText().toString());NetworkCatalog fresh=new NetworkCatalog(a);fresh.addExit(name.getText().toString().trim(),region.getText().toString().trim(),host.getText().toString().trim(),number,user.getText().toString(),password.getText().toString());catalog=fresh;d.dismiss();reload();if(next!=null)next.run();}catch(Exception e){error.setText(e instanceof NumberFormatException?"端口应为 1–65535":e.getMessage());d.resize();}});d.show();}
  void subscriptionDetail(JSONObject s){ReferenceUi.Modal d=new ReferenceUi.Modal(a,"订阅详情");field(d,"名称",s.optString("name"));field(d,"入口数量",EntrySelection.strings(s.optJSONArray("nodes")).size()+" 个");field(d,"更新于",updated(s.optLong("updatedAt")));d.note("更新仅更新可选入口；已连接窗口在保存并应用后使用新配置。");d.buttons("关闭",d::dismiss,"更新订阅",()->{d.dismiss();loadPool(s,true,null);});d.show();}
  void exitDetail(JSONObject e){ReferenceUi.Modal d=new ReferenceUi.Modal(a,"出口详情");field(d,"名称",e.optString("name"));field(d,"地区",e.optString("region").isEmpty()?"未标注":e.optString("region"));field(d,"出口 IP",e.optString("verifiedIp").isEmpty()?"待核验":e.optString("verifiedIp"));field(d,"服务器",e.optString("host")+":"+e.optInt("port"));field(d,"使用窗口",uses(e.optString("id"))+" 个");d.buttons("关闭",d::dismiss,"核验出口",()->{List<Integer> owners=new ArrayList<>();for(int i=0;i<windows.length();i++){WindowNetworkState s=state(windows.optJSONObject(i));if(s.internal&&s.connected&&e.optString("id").equals(NetworkCatalog.exitId(s.config)))owners.add(s.slot);}if(owners.isEmpty()){d.note("此出口尚无已连接窗口。保存窗口配置并连接后即可核验。");d.resize();return;}d.dismiss();operate(owners.get(0),"verify");});d.show();}
  void operate(int slot,String action){ReferenceUi.Modal d=new ReferenceUi.Modal(a,action.equals("measure")?"完整线路测速":action.equals("verify")?"核验出口":"重新连接");d.body.addView(DesignUi.progress(a,action.equals("measure")?"正在测量入口与固定出口的完整线路…":"正在检查此窗口网络…",""));d.buttons("收起",d::dismiss,"",()->{});d.show();NetworkBridge.run(a,slot,action,null,null,(ok,message,snapshot)->{if(closed||a.isDestroyed())return;reload();if(d.isShowing()){d.body.removeAllViews();TextView result=ReferenceUi.text(a,message,15,ok?ReferenceUi.GREEN:ReferenceUi.RED,true);d.body.addView(result);d.buttons("关闭",d::dismiss,"",()->{});d.resize();}});}
  void networkMode(int slot){if(catalog==null){afterRead=()->networkMode(slot);reload();return;}ReferenceUi.Modal d=new ReferenceUi.Modal(a,"网络方式 · "+Profiles.display(a,slot));choice(d,"订阅入口 + 固定出口","",false,()->{d.dismiss();for(int i=0;i<windows.length();i++)if(windows.optJSONObject(i).optJSONObject("row").optInt("slot")==slot){edit(windows.optJSONObject(i));return;}});choice(d,"手机网络 / 手机 VPN","",false,()->{d.dismiss();external(slot,false);});choice(d,"应用专用代理","",false,()->{d.dismiss();external(slot,true);});d.show();}
  void external(int slot,boolean proxy){ReferenceUi.Modal d=new ReferenceUi.Modal(a,proxy?"应用专用代理":"手机网络 / VPN");SharedPreferences prefs=Profiles.context(a,slot).getSharedPreferences("chat",0);EditText address=proxy?DesignUi.input(d.body,"代理地址",prefs.getString("proxy",""),"http://主机:端口 或 socks://主机:端口"):null;CheckBox vpn=new CheckBox(a);vpn.setText("手机 VPN 断开时暂停联网");vpn.setTextSize(13);vpn.setChecked(prefs.getBoolean("requireExternalVpn",true));d.body.addView(vpn);TextView error=ReferenceUi.text(a,"",12,ReferenceUi.RED,false);d.body.addView(error);String baseline=NativeNetwork.hash(new SecretStore(Profiles.context(a,slot)).settings().toString());d.buttons("取消",d::dismiss,"保存并应用",()->{String value=proxy?address.getText().toString().trim():"";if(proxy&&!MainActivity.validProxy(value)){address.setError("填写有效的 HTTP / SOCKS 代理地址");return;}d.primary().setEnabled(false);NetworkBridge.run(a,slot,"external",J.obj("proxy",value,"requireExternalVpn",vpn.isChecked()),baseline,(ok,message,state)->{if(closed||a.isDestroyed())return;reload();if(ok)d.dismiss();else{error.setText(message);d.primary().setEnabled(true);d.resize();}});});d.show();}
